// ============================================================
// view-state.ts — Pure query-string serialization for deeplinking.
//
// Converts a canonical `ViewState` object to/from a URL query string.
// This module is intentionally PURE: no DOM access, no `state.js` import,
// no app side effects — so it is unit-testable under `node --test` and
// reusable for breadcrumbs / an AI "jump to view" tool later.
//
// ⚠️  KEEP IN SYNC: this module is the source of truth for the full-app deeplink
//     params. Whenever you ADD, REMOVE, or CHANGE a param here (parseViewState /
//     serializeViewState / the shape below), update the reference doc in the SAME
//     change:  docs/deeplink-params.md
//     (it also covers the /renderproof page params and the proof `deeplink` field.)
//
// Canonical ViewState shape (all fields optional):
//   {
//     builtin,            // built-in lesson name           -> ?builtin=
//     scene,              // custom scene file path         -> ?scene=
//     view,               // 'math' (Math tab); scene=default  -> ?view=
//     panel,              // 'chat' (right panel); doc=default -> ?panel=
//     pp,                 // true => proof panel open           -> ?pp=1
//     dock,               // true => graph docked (split) view -> ?dock=1 (only true serializes; false/absent omitted)
//     sc,                 // scene id (resolved)            -> ?sc=
//     st,                 // step id; absent => base step   -> ?st=
//     pf,                 // proof id                       -> ?pf=
//     ps,                 // proof step id; absent => goal  -> ?ps=
//     nodes: [id, ...],   // ordered selection, last=active -> ?nodes=a,b,c
//     sliders: {id: num}, // parameter overrides            -> ?sl=id~val,...
//     cv,                 // selected camera-view preset    -> ?cv=iso
//     proj,               // 'orthographic'; perspective=default -> ?proj=orthographic
//     oz,                 // orthographic visible half-height (world) -> ?oz=3.2
//     cam: {              // camera (data-space)            -> ?cam=px,py,pz,tx,ty,tz[,ux,uy,uz]
//       position:[x,y,z], target:[x,y,z], up?:[x,y,z]
//     },
//     fa,                 // open Function Analysis artifact id             -> ?fa=
//     fax,                // expression to analyze when `fa` doesn't resolve -> ?fax=
//     aa,                 // auto-ask: a chat message to fire ONCE on boot -> ?aa=
//     pa,                 // pre-baked proof animation to load ONCE (<domain>/<name>) -> ?pa=
//     pas,                // step to open that animation on (with pa)            -> ?pas=
//   }
//
// NOTE: `aa`, `pa`, `pas` and `fax` are fire-once boot DIRECTIVES, not canonical shareable
// state — they are parsed but deliberately NOT re-serialized, so the post-apply
// replaceView() strips them from the URL (preventing a re-fire on reload / back / forward).
// `fa` IS serialized: it names an analysis that already exists in this session, so it
// describes the restorable view (Back closes the page, Forward reopens it).
// ============================================================

/**
 * Camera as it rides in the URL — DATA space, matching scene JSON.
 * Fixed-length tuples (rather than `number[]`) so the vectors can go straight
 * into coords.js's `Vec3` conversions without a cast; decodeCamera() below
 * only ever produces exactly-three-element vectors.
 */
export interface ViewStateCamera {
    position: [number, number, number];
    target: [number, number, number];
    up?: [number, number, number];
}

/**
 * The canonical deeplink state. Every field is optional; see the header block
 * above for what each one maps to in the query string.
 */
export interface ViewState {
    builtin?: string;
    scene?: string;
    view?: string;
    panel?: string;
    pp?: boolean;
    dock?: boolean;
    sc?: string;
    st?: string;
    pf?: string;
    ps?: string;
    nodes?: string[];
    sliders?: Record<string, number>;
    cv?: string;
    proj?: string;
    oz?: number;
    cam?: ViewStateCamera;
    fa?: string;
    fax?: string;
    aa?: string;
    pa?: string;
    pas?: number;
}

const CAM_DECIMALS = 4;
const DEFAULT_UP = [0, 1, 0];

// ----- Number / string helpers -----

/** Round to `dp` decimals and stringify, dropping trailing zeros. */
export function fmtNum(n: number, dp: number = CAM_DECIMALS): string {
    if (!Number.isFinite(n)) return '0';
    const f = Math.pow(10, dp);
    return String(Math.round(n * f) / f);
}

// Minimal percent-encoding that keeps the compact separators (`,` `~`)
// readable. URLSearchParams parsing decodes these fine on the way back.
function encMin(v: unknown): string {
    return encodeURIComponent(String(v)).replace(/%2C/gi, ',').replace(/%7E/gi, '~');
}

/** One `key=value` pair on its way into the query string. */
type QueryPair = [string, string | number | null | undefined];

function buildQuery(pairs: QueryPair[]): string {
    return pairs
        .filter(([, v]) => v !== undefined && v !== null && v !== '')
        .map(([k, v]) => `${k}=${encMin(v)}`)
        .join('&');
}

/**
 * Stable slug from a human title: lowercase, non-alphanumerics -> '-',
 * collapse/trim hyphens. Empty input yields ''.
 */
export function slugify(title: unknown): string {
    return String(title == null ? '' : title)
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
}

// ----- Camera encode / decode -----

/** Encode camera to compact `px,py,pz,tx,ty,tz[,ux,uy,uz]` (data-space). */
export function encodeCamera(cam: ViewStateCamera | null | undefined): string {
    if (!cam || !Array.isArray(cam.position) || !Array.isArray(cam.target)) return '';
    const p = cam.position, t = cam.target;
    const nums = [p[0], p[1], p[2], t[0], t[1], t[2]];
    const up = Array.isArray(cam.up) ? cam.up : null;
    // Only include `up` when it deviates from the default [0,1,0].
    if (up && !(up[0] === DEFAULT_UP[0] && up[1] === DEFAULT_UP[1] && up[2] === DEFAULT_UP[2])) {
        nums.push(up[0], up[1], up[2]);
    }
    return nums.map((n) => fmtNum(Number(n))).join(',');
}

/** Decode `px,py,pz,tx,ty,tz[,ux,uy,uz]` back to a camera object, or null. */
export function decodeCamera(str: string | null | undefined): ViewStateCamera | null {
    if (!str) return null;
    const segs = String(str).split(',');
    // The format is exactly 6 (position+target) or 9 (with up) numbers.
    // Reject any other length and any empty segment (e.g. a trailing comma,
    // which would otherwise coerce to a spurious 0).
    if (segs.length !== 6 && segs.length !== 9) return null;
    if (segs.some((s) => s.trim() === '')) return null;
    const parts = segs.map(Number);
    if (parts.some((n) => !Number.isFinite(n))) return null;
    // The length check above guarantees indices 0..5 (and 0..8 below) exist.
    const cam: ViewStateCamera = {
        position: [parts[0]!, parts[1]!, parts[2]!],
        target: [parts[3]!, parts[4]!, parts[5]!],
    };
    if (parts.length === 9) cam.up = [parts[6]!, parts[7]!, parts[8]!];
    return cam;
}

// ----- ViewState <-> query string -----
// Adding/changing a param below? Update docs/deeplink-params.md in the same change.

/** Serialize a ViewState to a query string (no leading '?'). */
export function serializeViewState(vs: ViewState | null | undefined): string {
    if (!vs) return '';
    const pairs: QueryPair[] = [];
    if (vs.builtin) pairs.push(['builtin', vs.builtin]);
    else if (vs.scene) pairs.push(['scene', vs.scene]);

    if (vs.view && vs.view !== 'scene') pairs.push(['view', vs.view]);
    if (vs.panel && vs.panel !== 'doc') pairs.push(['panel', vs.panel]);
    if (vs.pp) pairs.push(['pp', '1']);
    // Dock (split) layout: only the docked state is shareable — an absent param
    // leaves the recipient's own dock preference untouched (see parseViewState).
    if (vs.dock === true) pairs.push(['dock', '1']);

    if (vs.sc != null && vs.sc !== '') pairs.push(['sc', vs.sc]);
    if (vs.st != null && vs.st !== '') pairs.push(['st', vs.st]);
    if (vs.pf != null && vs.pf !== '') pairs.push(['pf', vs.pf]);
    if (vs.ps != null && vs.ps !== '') pairs.push(['ps', vs.ps]);
    // Function Analysis page open on artifact `fa`. Session-scoped ids: a link
    // shared into a fresh session won't resolve it, which is why the producer
    // (the proof widget's ƒ button) sends `fax` — the expression — instead.
    if (vs.fa != null && vs.fa !== '') pairs.push(['fa', vs.fa]);

    if (Array.isArray(vs.nodes) && vs.nodes.length) {
        pairs.push(['nodes', vs.nodes.map((id) => String(id)).join(',')]);
    }

    if (vs.sliders && typeof vs.sliders === 'object') {
        // Sort by id so equivalent ViewStates serialize identically (stable
        // URLs + reliable equality-by-serialization), regardless of key order.
        const packed = Object.entries(vs.sliders)
            .filter(([, val]) => Number.isFinite(Number(val)))
            .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
            .map(([id, val]) => `${id}~${fmtNum(Number(val))}`)
            .join(',');
        if (packed) pairs.push(['sl', packed]);
    }

    if (vs.cv) pairs.push(['cv', vs.cv]);
    if (vs.proj && vs.proj !== 'perspective') pairs.push(['proj', vs.proj]);
    // Number.isFinite() is the guard: it is only true for a real number here.
    if (Number.isFinite(vs.oz)) pairs.push(['oz', fmtNum(vs.oz!)]);

    if (vs.cam) {
        const enc = encodeCamera(vs.cam);
        if (enc) pairs.push(['cam', enc]);
    }

    return buildQuery(pairs);
}

/** Parse a query string (or URLSearchParams) into a ViewState. */
export function parseViewState(search: string | URLSearchParams | null | undefined): ViewState {
    // Adding/changing a param below? Update docs/deeplink-params.md in the same change.
    let params;
    if (search instanceof URLSearchParams) {
        params = search;
    } else {
        const s = String(search == null ? '' : search).replace(/^\?/, '');
        params = new URLSearchParams(s);
    }

    const vs: ViewState = {};
    const builtin = params.get('builtin');
    const scene = params.get('scene');
    if (builtin) vs.builtin = builtin;
    else if (scene) vs.scene = scene;

    const view = params.get('view');
    if (view) vs.view = view;

    const panel = params.get('panel');
    if (panel) vs.panel = panel;

    // Auto-ask: a chat message to fire once on boot (see header note). Capped to
    // bound the chat payload; not serialized, so it never round-trips into a URL.
    const aa = params.get('aa');
    if (aa) vs.aa = String(aa).slice(0, 2000);

    // Pre-baked proof animation to load on boot: a "<domain>/<name>" slug under
    // proofs/domains/. Like `aa`, a load-once directive — parsed but NOT serialized.
    const pa = params.get('pa');
    // Exactly "<domain>/<name>" — mirror graph-view's _PROOF_PATH_RE so a slug the
    // dock will reject (leading/extra slashes) can't set vs.pa and force Math view.
    if (pa && /^[A-Za-z0-9_-]+\/[A-Za-z0-9_-]+$/.test(pa)) vs.pa = pa;
    // pas: which step of the pre-baked animation to open on (load-once, not serialized).
    const pas = params.get('pas');
    if (pas != null && /^\d{1,4}$/.test(pas)) vs.pas = Number(pas);

    const pp = params.get('pp');
    if (pp === '1' || pp === 'true') vs.pp = true;

    // Dock (split) view. Explicit only: `dock=1`/`true` forces split, `dock=0`/
    // `false` forces full — absent leaves `vs.dock` undefined so applyViewState
    // won't touch the user's persisted dock preference on an ordinary link.
    const dock = params.get('dock');
    if (dock === '1' || dock === 'true') vs.dock = true;
    else if (dock === '0' || dock === 'false') vs.dock = false;

    const sc = params.get('sc');
    const st = params.get('st');
    const pf = params.get('pf');
    const ps = params.get('ps');
    if (sc) vs.sc = sc;
    if (st) vs.st = st;
    if (pf) vs.pf = pf;
    if (ps) vs.ps = ps;

    // Function Analysis deeplink. `fa` names an artifact already attached to the
    // target step (serialized — see above); `fax` carries the LaTeX to analyze when
    // no such artifact exists, which is the cross-session path (a proof widget's ƒ
    // button knows the expression, never an id). Both capped so a malformed link
    // can't push an unbounded payload into the expert request.
    const fa = params.get('fa');
    if (fa) vs.fa = String(fa).slice(0, 200);
    const fax = params.get('fax');
    if (fax) vs.fax = String(fax).slice(0, 1000);

    const nodes = params.get('nodes');
    if (nodes) {
        const ids = nodes.split(',').map((s) => s.trim()).filter(Boolean);
        if (ids.length) vs.nodes = ids;
    }

    const sl = params.get('sl');
    if (sl) {
        const sliders: Record<string, number> = {};
        for (const pair of sl.split(',')) {
            const idx = pair.indexOf('~');
            if (idx <= 0) continue;
            const id = pair.slice(0, idx);
            const val = Number(pair.slice(idx + 1));
            if (id && Number.isFinite(val)) sliders[id] = val;
        }
        if (Object.keys(sliders).length) vs.sliders = sliders;
    }

    const cv = params.get('cv');
    if (cv) vs.cv = cv;

    const proj = params.get('proj');
    if (proj) vs.proj = proj;

    const oz = params.get('oz');
    if (oz != null && oz !== '') {
        const n = Number(oz);
        if (Number.isFinite(n)) vs.oz = n;
    }

    const cam = decodeCamera(params.get('cam'));
    if (cam) vs.cam = cam;

    return vs;
}

/** True when two ViewStates serialize identically (cheap structural eq). */
export function viewStatesEqual(
    a: ViewState | null | undefined,
    b: ViewState | null | undefined,
): boolean {
    return serializeViewState(a) === serializeViewState(b);
}
